const existing = new Set(game.scenes.filter(s => s.flags?.[MID]).map(s => s.name));
const todo = docs.filter(d => !existing.has(d.name));

let created = 0; const failures = [];
const CHUNK = 60;
for (let i = 0; i < todo.length; i += CHUNK) {
  const batch = todo.slice(i, i + CHUNK).map(d => ({ ...d, folder: folders[d.flags[MID].folder] }));
  try {
    const made = await Scene.createDocuments(batch, { keepId: false, render: false, renderSheet: false });
    created += made.length;
  } catch (e) {
    for (const one of batch) {
      try { await Scene.create(one, { render: false }); created++; }
      catch (e2) { failures.push({ name: one.name, err: String(e2).slice(0, 110) }); }
    }
  }
}
return { alreadyPresent: existing.size, attempted: todo.length, created, failed: failures.length,
         failures: failures.slice(0, 8), totalScenesNow: game.scenes.size };

