const MID = "pentaryn-seafoot-maps";
const docs = await (await fetch(`/modules/${MID}/scenes.import.json`)).json();
const mine = game.scenes.filter(s => s.flags?.[MID]);

const srcTot = docs.reduce((a, d) => ({
  walls: a.walls + (d.walls?.length ?? 0),
  lights: a.lights + (d.lights?.length ?? 0),
  sounds: a.sounds + (d.sounds?.length ?? 0)
}), { walls: 0, lights: 0, sounds: 0 });
const gotTot = mine.reduce((a, s) => ({
  walls: a.walls + s.walls.size, lights: a.lights + s.lights.size, sounds: a.sounds + s.sounds.size
}), { walls: 0, lights: 0, sounds: 0 });

// per-scene spot check on 10 random scenes
const byName = new Map(docs.map(d => [d.name, d]));
const sample = mine.sort(() => Math.random() - 0.5).slice(0, 10);
const spot = [];
for (const s of sample) {
  const d = byName.get(s.name);
  const bg = s.levels.contents[0]?.background?.src;
  const ok = await fetch("/" + bg, { method: "HEAD" }).then(r => r.ok).catch(() => false);
  spot.push({
    name: s.name.slice(0, 34),
    walls: s.walls.size === (d.walls?.length ?? 0),
    sounds: s.sounds.size === (d.sounds?.length ?? 0),
    grid: s.grid.size === d.grid?.size,
    dims: s.width === d.width && s.height === d.height,
    imgOk: ok, thumb: !!s.thumb
  });
}

const gridSizes = {};
for (const s of mine) gridSizes[s.grid.size] = (gridSizes[s.grid.size] ?? 0) + 1;

return {
  counts: { scenes: mine.length, expected: docs.length, match: mine.length === docs.length },
  totals: { source: srcTot, migrated: gotTot,
            match: JSON.stringify(srcTot) === JSON.stringify(gotTot) },
  thumbnails: mine.filter(s => s.thumb).length,
  noBackground: mine.filter(s => !s.levels.contents[0]?.background?.src).length,
  gridSizeDistribution: gridSizes,
  folders: game.folders.filter(f => f.type === "Scene" && f.folder?.name === "Seafoot Maps")
             .map(f => `${f.name}: ${mine.filter(s => s.folder?.id === f.id).length}`).sort(),
  spotCheck: spot,
  spotAllPass: spot.every(x => x.walls && x.sounds && x.grid && x.dims && x.imgOk)
};

