  const cols = Math.min(Math.ceil(Math.sqrt(toks.length)), 6);
  const spacing = Math.max(120, (scene.grid?.size || 100));
  const originX = cx - (cols - 1) * spacing / 2;
  const originY = cy - (Math.ceil(toks.length / cols) - 1) * spacing / 2;

  const specs = toks.map((t, i) => ({
    oldId: t.id, actorId: t.actorId, hidden: t.hidden, textureSrc: t.texture.src,
    x: originX + (i % cols) * spacing,
    y: originY + Math.floor(i / cols) * spacing,
  }));

  const isActive = (scene === canvas.scene);
  if (isActive) {
    // active/viewed scene: delete+recreate to dodge the animation-lock bug
    await scene.deleteEmbeddedDocuments("Token", specs.map(s => s.oldId));
    const toCreate = [];
    for (const spec of specs) {
      const actor = game.actors.get(spec.actorId);
      const td = await actor.getTokenDocument({x: spec.x, y: spec.y, hidden: spec.hidden});
      const obj = td.toObject();
      delete obj._id;
      obj.texture = { ...obj.texture, src: spec.textureSrc };
      toCreate.push(obj);
    }
    const created = await scene.createEmbeddedDocuments("Token", toCreate);
    results.push({ scene: scene.name, method: "recreate", center: {cx,cy}, count: created.length });
  } else {
    const res = await scene.updateEmbeddedDocuments("Token", specs.map(s => ({_id: s.oldId, x: s.x, y: s.y})), {diff: false});
    results.push({ scene: scene.name, method: "update", center: {cx,cy}, count: res.length });
  }
}
return results;

